class Solution {
    private int[] parent, rank, size;
    public int minMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.length;
        parent = new int[n]; rank = new int[n]; size = new int[n];
        for (int i = 0; i < n; i++) { parent[i] = i; size[i] = 1; }
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                if (graph[i][j] == 1) union(i, j);
        java.util.Map<Integer, Integer> compInfected = new java.util.HashMap<>();
        java.util.Set<Integer> initSet = new java.util.HashSet<>();
        for (int node : initial) initSet.add(node);
        for (int node : initial) {
            int root = find(node);
            compInfected.merge(root, 1, Integer::sum);
        }
        java.util.Arrays.sort(initial);
        int bestNode = initial[0], bestSave = 0;
        for (int node : initial) {
            int root = find(node);
            if (compInfected.get(root) == 1) {
                if (size[root] > bestSave) { bestSave = size[root]; bestNode = node; }
            }
        }
        return bestNode;
    }
    private int find(int x) { if (parent[x] != x) parent[x] = find(parent[x]); return parent[x]; }
    private void union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (rank[ra] < rank[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra; size[ra] += size[rb];
        if (rank[ra] == rank[rb]) rank[ra]++;
    }
}
